/* @autogenerated */
import { TestBed } from '@angular/core/testing';
import { MatDialog } from '@angular/material/dialog';
import { Observable, of, throwError } from 'rxjs';
import { EditConflictDialogComponent } from './edit-conflict-dialog.component';
import { EditConflict, EditConflictError } from './edit-conflict.model';
import { EditConflictService } from './edit-conflict.service';

interface Item {
  uid: string;
  name: string;
  version: number;
}

describe('EditConflictService', () => {
  let dialog: jasmine.SpyObj<MatDialog>;
  let service: EditConflictService;

  const conflict: EditConflict<Item> = {
    original: { uid: '1', name: 'A', version: 1 },
    sent: { uid: '1', name: 'Mine', version: 1 },
    current: { uid: '1', name: 'Theirs', version: 2 },
  };
  const merged: Item = { uid: '1', name: 'Mine', version: 2 };
  const conflictError = () => throwError(() => new EditConflictError(conflict, { status: 412 }));
  const closingWith = (...values: unknown[]) =>
    dialog.open.and.returnValues(...values.map((value) => ({ afterClosed: () => of(value) }) as any));

  beforeEach(() => {
    dialog = jasmine.createSpyObj<MatDialog>('MatDialog', ['open']);
    TestBed.configureTestingModule({ providers: [{ provide: MatDialog, useValue: dialog }] });
    service = TestBed.inject(EditConflictService);
  });

  it('resolve opens the dialog without closing on backdrop', () => {
    closingWith(merged);
    const fields = [{ name: 'name', label: 'x.name' }];
    let result: Item | null | undefined;

    service.resolve(conflict, fields).subscribe((value) => (result = value));

    expect(dialog.open).toHaveBeenCalledWith(
      EditConflictDialogComponent,
      jasmine.objectContaining({ data: { conflict, fields }, disableClose: true }),
    );
    expect(result).toEqual(merged);
  });

  it('resolve emits null when the dialog is dismissed', () => {
    closingWith(undefined);
    let result: Item | null | undefined;
    service.resolve(conflict, []).subscribe((value) => (result = value));
    expect(result).toBeNull();
  });

  it('save retries with the merged value and the current value as original', () => {
    closingWith(merged);
    const save = jasmine.createSpy('save').and.returnValues(conflictError(), of(merged)) as jasmine.Spy<
      (v: Item, o: Item) => Observable<Item>
    >;
    const onMerged = jasmine.createSpy('merged');
    let saved: Item | undefined;

    service
      .save({ value: conflict.sent, original: conflict.original, fields: [], save, merged: onMerged })
      .subscribe((value) => (saved = value));

    expect(save.calls.argsFor(1)).toEqual([merged, conflict.current]);
    expect(onMerged).toHaveBeenCalledWith(merged, conflict.current);
    expect(saved).toEqual(merged);
  });

  it('save repeats the cycle on a new conflict', () => {
    closingWith(merged, merged);
    const save = jasmine.createSpy('save').and.returnValues(conflictError(), conflictError(), of(merged));

    service.save({ value: conflict.sent, original: conflict.original, fields: [], save }).subscribe();

    expect(dialog.open).toHaveBeenCalledTimes(2);
    expect(save).toHaveBeenCalledTimes(3);
  });

  it('save completes without emitting when the user cancels', () => {
    closingWith(null);
    const save = jasmine.createSpy('save').and.returnValue(conflictError());
    const next = jasmine.createSpy('next');
    let completed = false;

    service
      .save({ value: conflict.sent, original: conflict.original, fields: [], save })
      .subscribe({ next, complete: () => (completed = true) });

    expect(next).not.toHaveBeenCalled();
    expect(completed).toBeTrue();
    expect(save).toHaveBeenCalledTimes(1);
  });

  it('save propagates other errors', () => {
    const save = jasmine.createSpy('save').and.returnValue(throwError(() => ({ status: 500 })));
    let error: any;

    service.save({ value: conflict.sent, original: conflict.original, fields: [], save }).subscribe({
      error: (err) => (error = err),
    });

    expect(error.status).toBe(500);
    expect(dialog.open).not.toHaveBeenCalled();
  });
});
